tasks = []
while True:
    try:
        line = input().strip()
    except EOFError:
        break
    if line == "quit":
        break
    if line.startswith("add "):
        tasks.append(line[4:].strip())
    elif line == "list":
        if not tasks:
            print("Пусто")
        for i, title in enumerate(tasks, 1):
            print(f"{i}. {title}")

